// sketch.ino
// Плата: ESP32-S3 (нативный USB, режим USB-OTG)
#include "USB.h"
#include "USBHIDKeyboard.h"

USBHIDKeyboard Keyboard;

const char* BAT_PATH = "%USERPROFILE%\\script.bat";

void setup() {
  Keyboard.begin();
  USB.begin();

  // Ждём, пока ОС распознает HID-устройство.
  // На ESP32-S3 перечисление медленнее, чем у Leonardo, поэтому пауза больше
  delay(5000);

  // Win + R -> cmd
  Keyboard.press(KEY_LEFT_GUI);
  Keyboard.press('r');
  delay(100);
  Keyboard.releaseAll();
  delay(1000);

  switchToEnglish();
  delay(200);

  Keyboard.print("cmd");
  pressEnter();
  delay(2000);

  switchToEnglish();
  delay(200);

  // Строка 1: @echo off
  Keyboard.print("echo @echo off>");
  Keyboard.print(BAT_PATH);
  pressEnter(); delay(200);

  // Строка 2: color 2 (пробел перед >> обязателен)
  Keyboard.print("echo color 2 >>");
  Keyboard.print(BAT_PATH);
  pressEnter(); delay(200);

  // Строка 3: dir/s
  Keyboard.print("echo dir/s>>");
  Keyboard.print(BAT_PATH);
  pressEnter(); delay(200);

  // Строка 4: goto x
  Keyboard.print("echo goto x>>");
  Keyboard.print(BAT_PATH);
  pressEnter(); delay(200);

  // Запуск
  Keyboard.print("start ");
  Keyboard.print(BAT_PATH);
  pressEnter();

  // Полный экран
  delay(2000);
  Keyboard.press(KEY_F11);
  delay(100);
  Keyboard.releaseAll();

  Keyboard.print("exit");
  pressEnter();
}

void switchToEnglish() {
  Keyboard.press(KEY_LEFT_CTRL);
  Keyboard.press(KEY_LEFT_SHIFT);
  Keyboard.press('1');
  delay(100);
  Keyboard.releaseAll();
  delay(200);
}

void pressEnter() {
  Keyboard.press(KEY_RETURN);
  delay(50);
  Keyboard.releaseAll();
}

void loop() {}
